/// 送料の計算。
///
/// ショップの規約: 商品代金(税込)が `freeThreshold` 円以上なら送料無料。それ未満は一律 `flatFee` 円。
public struct ShippingFee: Sendable {
    public var freeThreshold = 5_000
    public var flatFee = 550

    public init() {}

    public func fee(forSubtotal subtotal: Int) -> Int {
        subtotal > freeThreshold ? 0 : flatFee
    }
}

