import Testing
@testable import Shop

/// しきい値の1円下は送料がかかる。
@Test func justBelowThresholdIsCharged() {
    #expect(ShippingFee().fee(forSubtotal: 4_999) == 550)
}

/// しきい値の設定を変えても同じ規則。
@Test func customThresholdIsInclusive() {
    var fee = ShippingFee()
    fee.freeThreshold = 3_000
    #expect(fee.fee(forSubtotal: 3_000) == 0)
    #expect(fee.fee(forSubtotal: 2_999) == 550)
}

